INSERT INTO public.group_members (group_id, user_id)
SELECT g.id, p.id
FROM public.groups g
CROSS JOIN public.user_profiles p
WHERE g.name = 'PT100'
  AND p.is_approved = true
  AND p.is_removed = false
ON CONFLICT (group_id, user_id) DO NOTHING;
